import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Concepts and Execution Model","description":"","frontmatter":{},"headers":[],"relativePath":"flow-editor/concepts.md","filePath":"flow-editor/concepts.md"}'),o={name:"flow-editor/concepts.md"};function n(d,e,r,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="concepts-and-execution-model" tabindex="-1">Concepts and Execution Model <a class="header-anchor" href="#concepts-and-execution-model" aria-label="Permalink to &quot;Concepts and Execution Model&quot;">​</a></h1><p>Understanding how a run actually proceeds is the difference between a strategy that fires once and one that fires twice.</p><h2 id="nodes-edges-handles" tabindex="-1">Nodes, edges, handles <a class="header-anchor" href="#nodes-edges-handles" aria-label="Permalink to &quot;Nodes, edges, handles&quot;">​</a></h2><p>A workflow is a set of <strong>nodes</strong> joined by <strong>edges</strong>. Every node has an <code>id</code>, a <code>type</code>, a canvas <code>position</code>, and a <code>data</code> object holding its configuration.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;n2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getQuote&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;position&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELIANCE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;exchange&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NSE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outputVariable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;q&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Edges connect a <code>source</code> node to a <code>target</code> node:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;e1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;n1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;n2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>The complete contract for that JSON, every required key, what is validated and when, and copy-pasteable workflows, is in the <a href="./json-format.html">Workflow JSON Format</a>.</p><p>Condition nodes have <strong>two output handles</strong>. An edge leaving one carries a <code>sourceHandle</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;e2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cond&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sourceHandle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;buy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;e3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cond&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sourceHandle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;false&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;skip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>An edge from a condition <strong>without</strong> a <code>sourceHandle</code> is a <em>pass-through</em>: it is followed no matter which way the condition went. This is how you attach logging or alerting that should see every evaluation.</p><blockquote><p>Handle vocabulary differs by node: <code>positionCheck</code>, <code>fundCheck</code>, <code>priceCondition</code>, <code>timeWindow</code>, <code>varCondition</code>, <code>andGate</code>, <code>orGate</code> and <code>priceAlert</code> use <code>&quot;true&quot;</code>/<code>&quot;false&quot;</code>, while <code>timeCondition</code> and <code>notGate</code> use <code>&quot;yes&quot;</code>/<code>&quot;no&quot;</code>. The executor treats them as synonyms, but match the node&#39;s own vocabulary so saved graphs read cleanly. A <code>sourceHandle</code> on any other node type is rejected: those nodes emit a single unnamed output, so a named handle points at a socket that does not exist.</p></blockquote><h2 id="variables-and-interpolation" tabindex="-1">Variables and interpolation <a class="header-anchor" href="#variables-and-interpolation" aria-label="Permalink to &quot;Variables and interpolation&quot;">​</a></h2><p>Most data nodes accept an <code>outputVariable</code>. Set it, and the node&#39;s whole result is stored under that name for every downstream node to read with <code>&amp;#123;&amp;#123;...&amp;#125;&amp;#125;</code>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getQuote&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELIANCE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;exchange&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NSE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outputVariable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;q&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Downstream: <code>&amp;#123;&amp;#123;q.data.ltp&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;q.data.open&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;q.data.prev_close&amp;#125;&amp;#125;</code>.</p><p>Path syntax:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th></tr></thead><tbody><tr><td>Nested keys</td><td><code>&amp;#123;&amp;#123;order.data.orderid&amp;#125;&amp;#125;</code></td></tr><tr><td>Array index (positive only)</td><td><code>&amp;#123;&amp;#123;expiries.data[0]&amp;#125;&amp;#125;</code></td></tr><tr><td>Combined</td><td><code>&amp;#123;&amp;#123;chain.data.results[0].ce.ltp&amp;#125;&amp;#125;</code></td></tr></tbody></table><p>Built-ins are always available:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Example</th><th>Notes</th></tr></thead><tbody><tr><td><code>&amp;#123;&amp;#123;date&amp;#125;&amp;#125;</code></td><td><code>2026-07-30</code></td><td>Server calendar date</td></tr><tr><td><code>&amp;#123;&amp;#123;session_date&amp;#125;&amp;#125;</code></td><td><code>2026-07-30</code></td><td>Trading session date. Differs from <code>&amp;#123;&amp;#123;date&amp;#125;&amp;#125;</code> between midnight and the 03:00 IST rollover.</td></tr><tr><td><code>&amp;#123;&amp;#123;time&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;timestamp&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;iso_timestamp&amp;#125;&amp;#125;</code></td><td></td><td></td></tr><tr><td><code>&amp;#123;&amp;#123;hour&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;minute&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;second&amp;#125;&amp;#125;</code></td><td></td><td></td></tr><tr><td><code>&amp;#123;&amp;#123;day&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;month&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;year&amp;#125;&amp;#125;</code></td><td></td><td></td></tr><tr><td><code>&amp;#123;&amp;#123;weekday&amp;#125;&amp;#125;</code></td><td><code>Thursday</code></td><td>A name, so it cannot be compared numerically</td></tr><tr><td><code>&amp;#123;&amp;#123;weekday_num&amp;#125;&amp;#125;</code></td><td><code>4</code></td><td>1 = Monday. Use this in a condition.</td></tr><tr><td><code>&amp;#123;&amp;#123;quarter&amp;#125;&amp;#125;</code></td><td><code>3</code></td><td>1 through 4</td></tr><tr><td><code>&amp;#123;&amp;#123;week_of_year&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;day_of_year&amp;#125;&amp;#125;</code></td><td><code>31</code>, <code>211</code></td><td>ISO week, day of year</td></tr></tbody></table><p>For &quot;has a new day, week, month or quarter started&quot;, use the <a href="./node-reference.html"><code>calendar</code> node</a> rather than comparing these, it accounts for weekends and exchange holidays, which a <code>&amp;#123;&amp;#123;day&amp;#125;&amp;#125; == 1</code> test does not.</p><p><strong>If a path does not resolve, the literal <code>&amp;#123;&amp;#123;...&amp;#125;&amp;#125;</code> text is passed through.</strong> The workflow does not stop. This is deliberate, it makes typos visible in the execution log rather than crashing a live strategy, but it means you should read your logs after the first run.</p><p>Two places refuse that leniency, because a wrong value there routes a branch or places a trade:</p><ul><li>A <code>varCondition</code> whose operand does not resolve to a number refuses to evaluate rather than treating the text as zero, and takes neither branch.</li><li>An <strong>order node</strong> fails outright when one of its order-defining fields still holds an unresolved reference, rather than falling back to a field default. A missing <code>&amp;#123;&amp;#123;webhook.qty&amp;#125;&amp;#125;</code> used to become quantity <code>1</code>, and an unresolved <code>priceType</code> used to fall through to <code>MARKET</code>. The full list of protected fields is in <a href="./json-format.html">Workflow JSON Format</a>.</li></ul><h2 id="execution-order" tabindex="-1">Execution order <a class="header-anchor" href="#execution-order" aria-label="Permalink to &quot;Execution order&quot;">​</a></h2><p>A run starts at the single trigger node and walks the graph <strong>depth-first</strong>, following each outgoing edge in order. There is no parallelism and no scheduler, one node finishes completely before the next begins.</p><p>Three consequences matter:</p><p><strong>1. Order of nodes is the order you wire them.</strong> If a <code>varCondition</code> reads <code>&amp;#123;&amp;#123;rsi.latest.value&amp;#125;&amp;#125;</code>, the <code>indicator</code> node producing <code>rsi</code> must be an <em>ancestor</em>, not a sibling.</p><p><strong>2. Logic gates wait, then fire once.</strong> An <code>andGate</code> with two inputs is reached first by whichever input finishes first. The gate detects that its other input has not been evaluated yet and skips, leaving a log line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>andGate: waiting for 1 more input(s) before evaluating</span></span></code></pre></div><p>When the second input completes, its traversal reaches the gate again, now with a full set, and the gate evaluates exactly once:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AND Gate: [True, True] -&gt; True</span></span></code></pre></div><p><strong>3. A condition also evaluates once per run.</strong> A condition node is combinational in exactly the same way a gate is, so it is evaluated the first time the walk reaches it and its result is reused afterwards. Reachable by two paths, a condition used to run twice and follow its branch each time, so a diamond placed two orders from a single trigger. The second traversal now returns immediately, which skips nothing: the branch was already followed.</p><h2 id="wiring-gates-correctly" tabindex="-1">Wiring gates correctly <a class="header-anchor" href="#wiring-gates-correctly" aria-label="Permalink to &quot;Wiring gates correctly&quot;">​</a></h2><p><strong>A wire into a gate carries a value, not control flow.</strong> The gate reads each input&#39;s stored boolean, so a <code>False</code> condition reaches it exactly as a <code>True</code> one does and the gate&#39;s own <code>false</code> branch works. Pass-through wiring is the clearest way to say that:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;e3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;c1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;targetHandle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;input-0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;e4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;targetHandle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;input-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>An edge that also carries <code>sourceHandle: &quot;true&quot;</code> behaves the same way when its target is a gate, so an older graph wired that way is not broken. Prefer the pass-through form anyway: it reads as what the executor does, and it makes the difference from a real branch edge obvious.</p><p>Always pin gate inputs with <code>targetHandle: &quot;input-0&quot;</code>, <code>&quot;input-1&quot;</code>, and so on up to <code>inputCount - 1</code>. A slot number the gate does not have is rejected at import, because the gate would wait for an input that can never arrive.</p><p>Two things stop a gate answering on a partial picture:</p><p><strong><code>inputCount</code> is enforced.</strong> A gate configured for three inputs and wired for two errors rather than evaluating on part of the condition. Deleting one edge of a three-input AND used to silently downgrade it to a two-input AND, with the canvas still showing three slots.</p><p><strong>An errored input leaves the gate pending.</strong> A condition that could not be evaluated has no trustworthy result, so nothing is recorded for it and the gate never fires. It is not read as <code>False</code>. Previously an AND gate saw that placeholder <code>False</code>, computed a result, and drove its FALSE branch into a real order before the run was marked failed.</p><h2 id="a-node-that-cannot-get-an-answer-does-not-invent-one" tabindex="-1">A node that cannot get an answer does not invent one <a class="header-anchor" href="#a-node-that-cannot-get-an-answer-does-not-invent-one" aria-label="Permalink to &quot;A node that cannot get an answer does not invent one&quot;">​</a></h2><p><code>priceCondition</code>, <code>positionCheck</code> and <code>fundCheck</code> never checked whether the broker read succeeded, so a failed lookup gave <code>ltp = 0.0</code> or a zero-quantity position and the node still reported success. &quot;If LTP &lt; 100 then BUY&quot; fired on an expired session, and a <code>positionCheck</code> with no symbol answered <code>not_exists</code> unconditionally, opening the gate it was there to guard.</p><p>They now <strong>error and take neither branch</strong> when the read fails, and a condition node whose <code>field</code>, <code>operator</code> or <code>condition</code> is not one it recognises does the same. <code>false</code> is a real answer that routes the graph down the false path, which is not what &quot;the check never ran&quot; means.</p><table tabindex="0"><thead><tr><th>Situation</th><th>What happens</th></tr></thead><tbody><tr><td>A condition&#39;s broker read fails</td><td>The node errors and takes neither branch. Pass-through edges still run, so the failure is visible.</td></tr><tr><td>A condition cannot be evaluated</td><td>Neither branch, and any gate wired to it stays pending.</td></tr><tr><td>A gate has fewer edges wired than <code>inputCount</code></td><td>It errors instead of evaluating.</td></tr><tr><td>An order field holds an unresolved <code>&amp;#123;&amp;#123;reference&amp;#125;&amp;#125;</code></td><td>The node fails before the broker call.</td></tr><tr><td>Any node returns an error</td><td>Its branch stops, and the run is recorded as <code>failed</code>.</td></tr></tbody></table><p>The message is the broker&#39;s or the service&#39;s own text, insufficient funds, RMS blocked, symbol not found, in the run record and in the webhook reply. Every broker rejection used to surface as the literal string <code>node failed</code>.</p><h2 id="triggers" tabindex="-1">Triggers <a class="header-anchor" href="#triggers" aria-label="Permalink to &quot;Triggers&quot;">​</a></h2><p>A workflow must contain exactly one trigger, and it must be one of:</p><table tabindex="0"><thead><tr><th>Trigger</th><th>Fires when</th></tr></thead><tbody><tr><td><code>start</code></td><td>A schedule elapses (<code>once</code>, <code>daily</code>, <code>weekly</code>, <code>interval</code>)</td></tr><tr><td><code>webhookTrigger</code></td><td>An external system POSTs to the workflow&#39;s webhook URL</td></tr><tr><td><code>priceAlert</code></td><td>A polled LTP condition is met (one-shot by default)</td></tr><tr><td><code>orderUpdateTrigger</code></td><td>A matching order changes status (fill, reject, cancel)</td></tr></tbody></table><p><strong>Strict validation rejects a second trigger</strong> with a <code>multiple_triggers</code> error, so <strong>Run Now</strong>, activation, and import all refuse the graph. A partially edited workflow can still be saved with two triggers, and if one ever reached the executor it would walk from the first trigger it found and silently skip the second and everything downstream of it. If part of your graph mysteriously never executes, count the triggers first.</p><p>Because one trigger drives the whole graph, every branch shares the data nodes above it. That is also the cheapest layout: one <code>getQuote</code> feeding six branches is one broker call, whereas six separate workflows make six. Quotes and the order book are not cached, so the split layout is what trips a rate limit first.</p><p>Triggers are entry points, so <strong>their configuration cannot reference <code>&amp;#123;&amp;#123;variables&amp;#125;&amp;#125;</code></strong>: there is no upstream node to resolve against. The <code>orderUpdateTrigger</code> rejects an interpolated Order ID with a clear 400 rather than storing a placeholder that could never match.</p><p><code>marketHoursOnly: true</code> on a <code>start</code> node pauses the schedule outside the trading session. No time is hardcoded: the window comes from Tradeboard&#39;s own exchange calendar, so weekends, trading holidays, muhurat and other special sessions, and per-exchange hours are all inherited. MCX running to 23:55 and CRYPTO never closing are handled correctly.</p><p>Three optional fields on the same node narrow or move that window:</p><table tabindex="0"><thead><tr><th>Field</th><th>Effect</th></tr></thead><tbody><tr><td><code>marketHoursExchange</code></td><td>Which calendar to consult (default NSE)</td></tr><tr><td><code>marketHoursStart</code></td><td><code>HH:MM</code> IST override for the session start</td></tr><tr><td><code>marketHoursEnd</code></td><td><code>HH:MM</code> IST override for the session end</td></tr></tbody></table><p>An override changes the clock, never the calendar: a day the exchange is shut stays shut. These fields are re-read from the graph on every run, so editing them takes effect immediately without a deactivate/reactivate cycle. The trigger&#39;s own schedule still needs a reactivation when it changes.</p><h2 id="interval-schedules-are-anchored-to-the-clock" tabindex="-1">Interval schedules are anchored to the clock <a class="header-anchor" href="#interval-schedules-are-anchored-to-the-clock" aria-label="Permalink to &quot;Interval schedules are anchored to the clock&quot;">​</a></h2><p>An <code>interval</code> schedule fires on the next clock boundary the interval divides into, not on a phase set by whenever you switched the workflow on. A 5-minute job lands on :00, :05, :10, and stays there across restarts. It used to count from activation time, so &quot;every minute&quot; ran at 11:34:41, 11:35:41, and the phase changed every time the process came back.</p><p>That phase decides real outcomes for anything reading bars: whether the candle a strategy wants to compare has closed yet is a whole-candle difference.</p><p>Runs land a small offset past the boundary, <code>FLOW_INTERVAL_ALIGN_OFFSET</code>, 2 seconds by default. Not zero: firing exactly on the boundary races the bar that is closing, and whether the feed has opened the next one changes the answer. Sub-minute intervals are left unaligned, there is no meaningful boundary to align a 10-second job to.</p><p>The indicator and history nodes reuse a fetch for <code>FLOW_HISTORY_CACHE_TTL</code> seconds, 30 by default. That is under a 5-minute candle but half of a 1-minute one, so lower it for a 1-minute strategy or the run can act on the previous bar.</p><h2 id="streaming-subscriptions-end-with-the-workflow" tabindex="-1">Streaming subscriptions end with the workflow <a class="header-anchor" href="#streaming-subscriptions-end-with-the-workflow" aria-label="Permalink to &quot;Streaming subscriptions end with the workflow&quot;">​</a></h2><p>A <code>subscribeLtp</code> / <code>subscribeQuote</code> / <code>subscribeDepth</code> node opens a broker-side subscription against a process-wide WebSocket client, so one left behind is held for the life of the worker and counts against the per-broker symbol ceiling that <code>/trading</code> and the Sandbox engine share.</p><p><strong>Deactivating or deleting a workflow gives back everything it opened.</strong> You do not need an <code>unsubscribe</code> node for cleanup, only to drop a stream part way through a run.</p><p><code>unsubscribe</code> requires a <code>symbol</code> unless <code>streamType</code> is <code>all</code>. A specific mode with no symbol is refused, because the underlying call would clear every subscription on the instance, including the ones the Sandbox engine uses to trigger pending SL and LIMIT orders.</p><h2 id="execution-limits" tabindex="-1">Execution limits <a class="header-anchor" href="#execution-limits" aria-label="Permalink to &quot;Execution limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Max node depth</td><td>100</td></tr><tr><td>Max node visits per run</td><td>500</td></tr><tr><td>Concurrent runs of one workflow</td><td>1 (a second trigger returns <code>already_running</code>)</td></tr><tr><td>Max bars per history fetch</td><td>200 (see <a href="./market-data.html">Market Data</a>)</td></tr></tbody></table><h2 id="editing-a-workflow-as-json" tabindex="-1">Editing a workflow as JSON <a class="header-anchor" href="#editing-a-workflow-as-json" aria-label="Permalink to &quot;Editing a workflow as JSON&quot;">​</a></h2><p>The editor exports and re-imports JSON, which is how a strategy can be authored or reviewed as a file, or generated by an AI from the import spec. The full contract, the envelope, the node and edge shapes, the interpolation grammar and worked examples, is in <a href="./json-format.html">Workflow JSON Format</a>.</p><p><strong>Import always creates a new workflow.</strong> That is deliberate for sharing, but it means iterating on your own strategy would leave copies behind and change the webhook URL every time.</p><p>To update a workflow you already have, use <strong>Replace from JSON</strong> in the workflow menu. It swaps the nodes and edges in place and keeps:</p><ul><li>the workflow id and its <code>/flow/editor/&lt;id&gt;</code> URL</li><li>the webhook token and secret, so anything posting to it keeps working</li><li>the active state and the stored API key</li></ul><p>It is validated exactly like Import: an incomplete graph is rejected with the reason rather than saved to fail later, and legacy fields from an older export are upgraded on the way in.</p><p>One thing to watch: node edits apply from the next run, because the graph is re-read every time. The <strong>trigger</strong> is different - its schedule and any price or order watch are registered when you activate. If you change the trigger, the editor tells you to deactivate and reactivate.</p><p>For scripted use there is also <code>scripts/update_flow_workflow.py --id &lt;id&gt; --file strategy.json</code>, with <code>--dry-run</code> to preview.</p><p>A workflow can be checked before it is imported. Flow ignores a <code>data</code> key nothing reads, so <code>strikeOffset</code> where the field is <code>offset</code> imports cleanly, runs successfully, and silently uses the default. The repository ships a checker that catches that and a few related near-certain mistakes, see <a href="./json-format.html">Workflow JSON Format</a>.</p>`,76)])])}const u=t(o,[["render",n]]);export{k as __pageData,u as default};
